WITH Src AS (SELECT *, INITCAP(TRIM(carrier)) AS carrier_title FROM shipments WHERE carrier NOT IN ('UPS', 'Kerry', 'FedEx') AND cost >= 93), summary AS (SELECT DATE_FORMAT(delivered_date, 'yyyy-MM') AS delivered_month, carrier, COUNT(DISTINCT cost) AS unique_carriers, COUNT(CASE WHEN carrier = 'DHL' THEN 1 END) AS dhl_count FROM Src GROUP BY DATE_FORMAT(delivered_date, 'yyyy-MM'), carrier) SELECT * FROM summary WHERE dhl_count > 4 ORDER BY dhl_count DESC;
